export type Domain = "ai" | "cloud" | "security" | "data" | "webdev" | "devops" | "programming" | "cs" | "networking" | "marketing" | "career";
export type Level = "beginner" | "intermediate" | "advanced";
export type Cost = "free-cert" | "free-learn-paid-cert" | "free-learn-paid-exam" | "limited-time" | "free-no-cert";
export type Credential = "certificate" | "badge" | "exam" | "none";

export type Course = {
  id: string;
  title: string;
  provider: string;
  domain: Domain;
  level: Level;
  /** Approximate learning time in hours, only when the provider states it. */
  hours?: number;
  cost: Cost;
  credential: Credential;
  summary: string;
  url: string;
  trending?: boolean;
  /** Date (YYYY-MM-DD) the cost and credential were confirmed on the provider's page. */
  verified?: string;
  /** Curated learning priority (not a learner rating), from 1 to 3 stars. */
  priority?: 1 | 2 | 3;
  priorityReason?: string;
  /** Last day of a time-limited offer (YYYY-MM-DD). Only set from the provider's own announcement. */
  closesOn?: string;
  /** What the date means, in plain words. */
  deadlineNote?: string;
  /** NPTEL / SWAYAM details. Leave a field out unless it was confirmed on nptel.ac.in or swayam.gov.in. */
  academic?: {
    examFee?: string;
    weeks?: number;
    semester?: string;
    /** Eligible for credit transfer under UGC/AICTE rules (the learner's college decides). */
    credit?: boolean;
    checked: string; // YYYY-MM-DD
    source: string;
  };
};

